// Atlas's character: a tiny figure holding up the globe. One Lottie file per
// colour (assets/animations/atlas-mark.*.json, generated by
// scripts/build-ui-animations.mjs) holding three segments that all start and
// end on the same rest pose, so they can be played in any order.

import { useEffect, useRef } from "react";
import type { StyleProp, ViewStyle } from "react-native";
import LottieView from "lottie-react-native";
import { useReducedMotion } from "react-native-reanimated";

const SOURCES = {
    yellow: require("@/assets/animations/atlas-mark.yellow.json"),
    grey: require("@/assets/animations/atlas-mark.grey.json"),
    ink: require("@/assets/animations/atlas-mark.ink.json"),
} as const;

// Frame ranges — keep in sync with ATLAS_SEGMENTS in the generator.
const SEGMENTS = {
    hop: [0, 75],
    wave: [75, 165],
    think: [165, 285],
} as const;

export type AtlasMarkColor = keyof typeof SOURCES;
export type AtlasMarkIntro = "hop" | "wave";

export interface AtlasMarkProps {
    size: number;
    color: AtlasMarkColor;
    /** Played once on mount. */
    intro?: AtlasMarkIntro | null;
    /** Spin the globe on a loop (Atlas is working on a reply). */
    busy?: boolean;
    /** Wave every so often while idle. */
    idleWave?: boolean;
    style?: StyleProp<ViewStyle>;
}

const IDLE_WAVE_MS = 9000;

export function AtlasMark({ size, color, intro = null, busy = false, idleWave = false, style }: AtlasMarkProps) {
    const ref = useRef<LottieView>(null);
    const reduceMotion = useReducedMotion();

    const play = (segment: keyof typeof SEGMENTS) => {
        if (reduceMotion) return;
        const [from, to] = SEGMENTS[segment];
        ref.current?.play(from, to);
    };

    // Intro once the view has mounted (an immediate play can be dropped on
    // Android before the composition has loaded).
    useEffect(() => {
        if (!intro || busy) return;
        const id = setTimeout(() => play(intro), 60);
        return () => clearTimeout(id);
    }, []);

    // Every segment begins and ends on the rest pose, so stopping the think
    // loop by resetting to frame 0 never visibly jumps the figure.
    const wasBusy = useRef(false);
    useEffect(() => {
        if (busy) {
            play("think");
        } else if (wasBusy.current) {
            ref.current?.reset();
        }
        wasBusy.current = busy;
    }, [busy]);

    useEffect(() => {
        if (!idleWave || busy || reduceMotion) return;
        const id = setInterval(() => play("wave"), IDLE_WAVE_MS);
        return () => clearInterval(id);
    }, [idleWave, busy, reduceMotion]);

    return (
        <LottieView
            ref={ref}
            source={SOURCES[color]}
            autoPlay={false}
            loop={busy}
            style={[{ width: size, height: size }, style]}
            resizeMode="contain"
        />
    );
}
